head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDFIS00200_00.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    //패널 라운드 처리
    $c.cm.PanelToGroupBox(panel_Top);

    //라디오 기본값 : 사업목적
    rdo_Fg.setValue("01");

    // rdo_Fg 값에따른 화면 처리
    scwin.fn_RdoFgOnSelChange();
};


/**
 *  라디오 OnSelChange
 */
scwin.fn_RdoFgOnSelChange = function() {
    var pageNum = rdo_Fg.getValue();
    if (pageNum == "08" || pageNum == "09" || pageNum == "12") {
        img_tmp_11.style.left = 1090 + 81;
        $c.stf.showObj(btn_Excel, false);
    } else {
        img_tmp_11.style.left = 1090;
        $c.stf.showObj(btn_Excel, true);
    }

    // 라디오 클릭 시 하단 프레임에 적당한 화면 세팅.
    scwin.fn_DisplayFrame(rdo_Fg.getValue());

    // 결산일자 visible
    scwin.fn_DisplayAcntclsDt();
};


/**
 *  하단 frome에 화면 표시
 */
scwin.fn_DisplayFrame = function(pVal) {
    $c.frame.path("../frame_body").srcUrl = scwin.fn_GetUrl(pVal);
};


/**
 *  url 만들기
 */
scwin.fn_GetUrl = function(pVal) {
    var vUrl = "./ULDFIS00200_" + pVal + ".gfm";
    return vUrl;
};


/**
 * 결산일자 visible
 */
scwin.fn_DisplayAcntclsDt = function() {
    // 주요주주, 배당, 관계회사현황
    if (rdo_Fg.getValue() == "03" || rdo_Fg.getValue() == "06" || rdo_Fg.getValue() == "18") {
        $c.stf.showObj(pnl_AcntclsDt1, true);
        $c.stf.showObj(pnl_AcntclsDt, false);
        //  기간 from~ to  셋팅	
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_AcntclsEndDt.setValue(vCurDate); // 현재날짜
        edt_AcntclsStrtDt.setValue($c.ut.cGetMinusDate2(vCurDate, 365));
        $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    } else if (rdo_Fg.getValue() == "05" || rdo_Fg.getValue() == "07" || rdo_Fg.getValue() == "08" ||
        rdo_Fg.getValue() == "09" || rdo_Fg.getValue() == "11" || rdo_Fg.getValue() == "12" ||
        rdo_Fg.getValue() == "13" || rdo_Fg.getValue() == "14" || rdo_Fg.getValue() == "15" ||
        rdo_Fg.getValue() == "17" || rdo_Fg.getValue() == "19" || rdo_Fg.getValue() == "20") {
        $c.stf.showObj(pnl_AcntclsDt, true);
        $c.stf.showObj(pnl_AcntclsDt1, false);
    } else {
        $c.stf.showObj(pnl_AcntclsDt, false);
        $c.stf.showObj(pnl_AcntclsDt1, false);
    }
};



/**
 *  결산일자 검색
 */
scwin.fn_SrchAcntclsDt = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("2");

    // 결산일자 visible = true인 경우만 조회, KisCd 필수
    if (pnl_AcntclsDt.style.display == "none" || $c.stf.getObjectValue(txb_KisCd) == "") {
        return;
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.AcntclsDt" + "&outputMessageId=FIS_ACNTCLS_DT" + "&param01=" + $c.stf.getObjectValue(txb_KisCd) + "&param02=" + $c.stf.getObjectValue(rdo_Fg);
    dts_AcntclsDt.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_AcntclsDt.Reset();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    if ($c.stf.getObjectValue(txb_CoSnm) == "") {
        alert("기업명을 입력하세요.");
        txb_CoSnm.focus();
        return false;
    }
    if (pnl_AcntclsDt.style.display != "none" && $c.stf.getObjectValue(cmb_AcntclsDt) == "") {
        alert("결산일자를 입력하세요.");
        cmb_AcntclsDt.focus();
        return false;
    }
    if (pnl_AcntclsDt1.style.display != "none") {
        if (!$c.stf.compareFromToDate2(edt_AcntclsStrtDt, edt_AcntclsEndDt)) {
            return false;
        }
        if ($c.stf.getObjectValue(edt_AcntclsStrtDt) == "") {
            alert("기간 시작일를 입력하세요.");
            return false;
        }
        if ($c.stf.getObjectValue(edt_AcntclsEndDt) == "") {
            alert("기간 종료일를 입력하세요.");
            return false;
        }
    }

    // 기업명은 있는데 기업코드가 없는 경우
    if ($c.stf.getObjectValue(txb_CoSnm) != "" && $c.stf.getObjectValue(txb_KisCd) == "") {
        scwin.fn_ComInfoSrch();
        return false;
    }
    return true;
};


/**
 * 기업현황 조회
 */
scwin.fn_Search = function() {
    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }
    if ($c.frame.path("../frame_body").fn_Search) {
        $c.frame.path("../frame_body").fn_Search();
    }
};



/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pFg) {
    if (pFg == "1") {
        dts_ComInfo.removeAll();
    } else if (pFg == "2") {
        dts_AcntclsDt.removeAll();
    }
};



/**
 * 기업정보 조회(명으로 조회)
 */
scwin.fn_ComInfoSrch = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("1");

    //기업명 없으면 중지.
    if ($c.stf.getObjectValue(txb_CoSnm) == "") {
        return;
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.comInfo" + "&outputMessageId=FIS_COM_INFO" + "&param01=" + $c.stf.getObjectValue(txb_CoSnm);
    dts_ComInfo.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_ComInfo.Reset();
};


/**
 * 기업검색 팝업
 */
scwin.fn_ComSrchOpen = async function() {
    await $c.frame.CreateDialogFrame("KIS_CD", "./ULDFIS00100_P1.gfm", "기업 검색", 100, 100, 640 + 20, 445 + 45, "window");
};


/**
 * 팝업으로 값을 넘김.
 */
scwin.fn_GetParKisCd = function() {
    var arrPar = new Array();
    arrPar[0] = txb_CoSnm.getValue(); // 기업명
    return arrPar;
};


/**
 * 팝업에서 넘어온 값 세팅.
 */
scwin.fn_SetParKisCd = function(arrPar) {
    txb_CoSnm.setValue(arrPar[0].CO_SNM); //기업명
    txb_KisCd.setValue(arrPar[0].KIS_CD); //기업코드

    if ($c.stf.getObjectValue(txb_KisCd) != "") {
        // 결산일자 visible = true인 경우
        if (pnl_AcntclsDt.style.display == "none" && pnl_AcntclsDt1.style.display == "none") {
            // 기업현황 조회
            scwin.fn_Search();
        } else {
            // 결산일자 조회.
            if (pnl_AcntclsDt.style.display != "none") {
                scwin.fn_SrchAcntclsDt();
            }
        }
    }
};





/**
 *  조회조건의 kisCd를 리턴.
 */
scwin.fn_GetKisCd = function() {
    return $c.stf.getObjectValue(txb_KisCd);
};


/**
 *  조회조건의 AcntclsDt를 리턴.
 */
scwin.fn_GetAcntclsDt = function() {
    return $c.stf.getObjectValue(cmb_AcntclsDt);
};


/**
 *  조회조건의 AcntclsStrtDt를 리턴.
 */
scwin.fn_GetAcntclsStrtDt = function() {
    return $c.stf.getObjectValue(edt_AcntclsStrtDt);
};


/**
 *  조회조건의 AcntclsEndDt를 리턴.
 */
scwin.fn_GetAcntclsEndDt = function() {
    return $c.stf.getObjectValue(edt_AcntclsEndDt);
};


/**
 *  그리드 헤더 명을 구한다.
 */
scwin.fn_GetGrdHeaderNm = function() {

	//----W-Craft WebSquare 변환 확인: fn_SetGrdHeaderNm----//
    if ($c.frame.path("../frame_body").fn_SetGrdHeaderNm) {
        var nCurrRow = dts_AcntclsDt.getRowPosition();
        var nTrgtRow = dts_AcntclsDt.getRowPosition() + 4;
        var aArray = new Array();
        var nArrRow = 0;
        for (var nRow = nCurrRow; nRow <= nTrgtRow; nRow++) {
            aArray[nArrRow] = {
                VALUE: dts_AcntclsDt.getCellData(nRow, "VALUE"),
                TEXT: dts_AcntclsDt.getCellData(nRow, "TEXT")
            };
            nArrRow++;
        }

        // 그리드 헤더 호출

	//----W-Craft WebSquare 변환 확인: fn_SetGrdHeaderNm----//
        $c.frame.path("../frame_body").fn_SetGrdHeaderNm(aArray);
    }
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.rdo_Fg_OnSelChange = function() {
    // 라디오 클릭
    scwin.fn_RdoFgOnSelChange();
};
scwin.btn_Search_onclick = function() {
    // 조회버튼 클릭
    scwin.fn_Search();
};
scwin.img_CoSearch_onclick = function() {
    // 기업검색팝업 오픈
    scwin.fn_ComSrchOpen();
};
scwin.txb_CoSnm_onkeydown = function() {
    // 기업명 키다운.
    if (event.keyCode == 13) {
        // 이게 왜 필요하냐구??? kisCD 세팅 후 마우스 포커스가 기업명에서 나갈때 onChange이벤트가 발생해서 kisCd를 지워버리기 때문이다
        $c.frame.focus();
        if ($c.stf.getObjectValue(txb_CoSnm) == "") {
            // 기업검색팝업 오픈
            scwin.fn_ComSrchOpen();
        } else {
            // 기업정보 조회
            scwin.fn_ComInfoSrch();
        }
    }
};
scwin.txb_CoSnm_onchange = function() {
    // 조회조건이 변경된 경우 초기화.
    txb_KisCd.setValue("");
};
scwin.dts_ComInfo_OnLoadCompleted = function(rowcount) {
    // 조회결과가 1개이면 기업개황 조회 아니면 기업팝업 오픈.
    if (rowcount == 1) {
        // 조회조건에 값을 세팅하고..
        txb_KisCd.setValue(dts_ComInfo.getCellData(0, "KIS_CD"));

        // 결산일자 visible = true인 경우
        if (pnl_AcntclsDt.style.display == "none" || pnl_AcntclsDt1.style.display == "none") {
            // 기업현황 조회
            scwin.fn_Search();
        } else {
            // 결산일자 조회.
            if (pnl_AcntclsDt.style.display != "none") {
                scwin.fn_SrchAcntclsDt();
            }
        }
    } else {
        scwin.fn_ComSrchOpen(); //기업검색 팝업 오픈

    }
};
scwin.dts_AcntclsDt_OnLoadCompleted = function(rowcount) {
    // 결산일자 OnLoadCompleted
    if (rowcount <= 0) {
        alert("결산일자가 존재하지 않습니다.");
    }
};
scwin.cmb_AcntclsDt_OnSelChange = function() {
    // 그리드 헤더에 명을 세팅. 필요한 경우만..
    scwin.fn_GetGrdHeaderNm();

    // 기업현황 조회
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {

	//----W-Craft WebSquare 변환 확인: fn_excel_download----//
    if ($c.frame.path("../frame_body").fn_excel_download) {

	//----W-Craft WebSquare 변환 확인: fn_excel_download----//
        $c.frame.path("../frame_body").fn_excel_download();
    }
};
scwin.img_AcntclsStrtDt_onclick = function() {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_AcntclsStrtDt);
};
scwin.img_AcntclsEndDt_onclick = function() {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_AcntclsEndDt);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_AcntclsStrtDt, edt_AcntclsEndDt);
};
